function linearSearch(nums: number[], target: number): number {
  for (let i = 0; i < nums.length; i++) {
    if (nums[i] === target) {
      return i;
    }
  }
  return -1;
}

function binarySearch(nums: number[], target: number): number {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo <= hi) {
    const mid = lo + Math.floor((hi - lo) / 2);
    if (nums[mid] === target) {
      return mid;
    } else if (nums[mid] < target) {
      lo = mid + 1;
    } else {
      hi = mid - 1;
    }
  }
  return -1;
}

function bubbleSort(nums: number[]): void {
  const n = nums.length;
  for (let i = 0; i < n - 1; i++) {
    for (let j = 0; j < n - 1 - i; j++) {
      if (nums[j] > nums[j + 1]) {
        [nums[j], nums[j + 1]] = [nums[j + 1], nums[j]];
      }
    }
  }
}

function selectionSort(nums: number[]): void {
  const n = nums.length;
  for (let i = 0; i < n - 1; i++) {
    let min = i;
    for (let j = i + 1; j < n; j++) {
      if (nums[j] < nums[min]) {
        min = j;
      }
    }
    [nums[i], nums[min]] = [nums[min], nums[i]];
  }
}

function insertionSort(nums: number[]): void {
  for (let i = 1; i < nums.length; i++) {
    const key = nums[i];
    let j = i - 1;
    while (j >= 0 && nums[j] > key) {
      nums[j + 1] = nums[j];
      j--;
    }
    nums[j + 1] = key;
  }
}

function mergeSort(nums: number[]): number[] {
  if (nums.length <= 1) {
    return nums;
  }
  const mid = Math.floor(nums.length / 2);
  const left = mergeSort(nums.slice(0, mid));
  const right = mergeSort(nums.slice(mid));
  return merge(left, right);
}

function merge(left: number[], right: number[]): number[] {
  const result: number[] = [];
  let i = 0;
  let j = 0;
  while (i < left.length && j < right.length) {
    if (left[i] <= right[j]) {
      result.push(left[i]);
      i++;
    } else {
      result.push(right[j]);
      j++;
    }
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

function quickSort(nums: number[], low: number, high: number): void {
  if (low < high) {
    const p = partition(nums, low, high);
    quickSort(nums, low, p - 1);
    quickSort(nums, p + 1, high);
  }
}

function partition(nums: number[], low: number, high: number): number {
  const pivot = nums[high];
  let i = low - 1;
  for (let j = low; j < high; j++) {
    if (nums[j] < pivot) {
      i++;
      [nums[i], nums[j]] = [nums[j], nums[i]];
    }
  }
  [nums[i + 1], nums[high]] = [nums[high], nums[i + 1]];
  return i + 1;
}

function heapSort(nums: number[]): void {
  const n = nums.length;
  for (let i = Math.floor(n / 2) - 1; i >= 0; i--) {
    siftDown(nums, i, n);
  }
  for (let i = n - 1; i > 0; i--) {
    [nums[0], nums[i]] = [nums[i], nums[0]];
    siftDown(nums, 0, i);
  }
}

function siftDown(nums: number[], root: number, size: number): void {
  while (true) {
    let largest = root;
    const left = 2 * root + 1;
    const right = 2 * root + 2;
    if (left < size && nums[left] > nums[largest]) {
      largest = left;
    }
    if (right < size && nums[right] > nums[largest]) {
      largest = right;
    }
    if (largest === root) {
      return;
    }
    [nums[root], nums[largest]] = [nums[largest], nums[root]];
    root = largest;
  }
}

class Graph {
  edges: Map<string, string[]>;

  constructor() {
    this.edges = new Map();
  }

  addEdge(from: string, to: string): void {
    if (!this.edges.has(from)) this.edges.set(from, []);
    if (!this.edges.has(to)) this.edges.set(to, []);
    this.edges.get(from)?.push(to);
    this.edges.get(to)?.push(from);
  }
}

function bfs(graph: Graph, start: string): string[] {
  const visited = new Set<string>([start]);
  const queue: string[] = [start];
  const order: string[] = [];
  for (let head = 0; head < queue.length; head++) {
    const node = queue[head];
    order.push(node);
    for (const neighbor of graph.edges.get(node) ?? []) {
      if (!visited.has(neighbor)) {
        visited.add(neighbor);
        queue.push(neighbor);
      }
    }
  }
  return order;
}

function dfs(graph: Graph, start: string): string[] {
  const visited = new Set<string>();
  const order: string[] = [];
  dfsVisit(graph, start, visited, order);
  return order;
}

function dfsVisit(
  graph: Graph,
  node: string,
  visited: Set<string>,
  order: string[],
): void {
  if (visited.has(node)) {
    return;
  }
  visited.add(node);
  order.push(node);
  for (const neighbor of graph.edges.get(node) ?? []) {
    dfsVisit(graph, neighbor, visited, order);
  }
}

type Edge = { to: string; weight: number };

class WeightedGraph {
  edges: Map<string, Edge[]>;

  constructor() {
    this.edges = new Map();
  }

  addEdge(from: string, to: string, weight: number): void {
    if (!this.edges.has(from)) this.edges.set(from, []);
    if (!this.edges.has(to)) this.edges.set(to, []);
    this.edges.get(from)?.push({ to, weight });
    this.edges.get(to)?.push({ to: from, weight });
  }
}

function dijkstra(
  graph: WeightedGraph,
  start: string,
  nodes: string[],
): Map<string, number> {
  const dist = new Map<string, number>();
  for (const node of nodes) {
    dist.set(node, Infinity);
  }
  dist.set(start, 0);

  const visited = new Set<string>();
  while (visited.size < nodes.length) {
    const current = closestUnvisited(dist, visited);
    if (current === null) {
      break;
    }
    visited.add(current);
    for (const edge of graph.edges.get(current) ?? []) {
      const newDist = (dist.get(current) ?? Infinity) + edge.weight;
      if (newDist < (dist.get(edge.to) ?? Infinity)) {
        dist.set(edge.to, newDist);
      }
    }
  }
  return dist;
}

function closestUnvisited(
  dist: Map<string, number>,
  visited: Set<string>,
): string | null {
  let best: string | null = null;
  let bestDist = Infinity;
  for (const [node, d] of dist) {
    if (!visited.has(node) && d < bestDist) {
      best = node;
      bestDist = d;
    }
  }
  return best;
}
